<script setup lang="ts">
const { asset } = useSiteUrl()
usePageSeo({ title: 'Journal', description: 'Project notes and practical engineering articles about Gonex, modular Go applications, typed APIs and explicit service boundaries.', path: '/blog/' })
const { data: articles } = await useAsyncData('blog-list', () => queryCollection('blog').order('date', 'DESC').all())
const category = ref('All')
const categories = computed(() => ['All', ...new Set(articles.value?.map(p => p.category) || [])])
const filtered = computed(() => articles.value?.filter(p => category.value === 'All' || p.category === category.value))
</script>
<template><div class="wrap blog-index"><span class="eyebrow">THE GONEX JOURNAL</span><h1>Notes from<br>the build<span class="brand-dot">.</span></h1><p class="blog-lead">Ideas, decisions, and a closer look at the code.</p><div class="blog-filters" aria-label="Article categories"><UButton v-for="c in categories" :key="c" color="neutral" :variant="category === c ? 'solid' : 'ghost'" :aria-pressed="category === c" @click="category = c">{{ c }}</UButton></div><div class="article-grid"><NuxtLink v-for="article in filtered" :key="article.path" :to="article.path + '/'" class="article-card"><div class="article-visual" :class="article.category === 'Architecture' ? 'architecture-visual' : 'intro-visual'"><template v-if="article.category === 'Architecture'"><span class="diagram-node">HTTP</span><span class="diagram-line" /><span class="diagram-node core">your service</span><span class="diagram-line" /><span class="diagram-node">gRPC</span></template><template v-else><img :src="asset('/brand/duck.webp')" width="155" height="143" alt="" /><span>hello,<br><em>goNex.</em></span></template></div><div class="article-meta">{{ article.category }} · <time :datetime="article.date">{{ new Date(article.date).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }) }}</time> · {{ article.readingTime }} min read</div><h2>{{ article.title }}</h2><p>{{ article.description }}</p><span class="text-link">Read the story <UIcon name="i-lucide-arrow-up-right" /></span></NuxtLink></div></div></template>
